    /// those out of a sentence is parsing prose.
    pub loop_abort: Option<LoopVerdict>,
    /// Where the session was written, if the caller asked for it to be.
    pub session_path: Option<PathBuf>,
}

impl RunFacts {
    /// One tool call on one server, counted.
    ///
    /// Called from `execute_tool_calls`, which is where a call becomes a fact: the
    /// registry has answered by then, and the server it answered from is on the result.
    /// A result with no server is a built-in tool -- `load_skill` -- and has no server
    /// to be counted against, so it is not.
    pub fn record_server_call(&mut self, server: Option<&str>, tool: &str) {
        let Some(server) = server else { return };
        *self
            .server_calls
            .entry(server.to_string())
            .or_default()
            .entry(tool.to_string())
            .or_insert(0) += 1;
    }
}

impl Default for RunFacts {
    /// `failed` rather than an empty word, because these facts are printed on paths that
    /// may not have reached `conclude` at all. A run that fell over before it could name
    /// its own ending did not complete, and the default has to be the word that says so
    /// rather than one that reads as a successful run with a blank label.
    fn default() -> Self {
        Self {
            started: String::new(),
            ended: String::new(),
            ended_because: "failed",
            seconds: 0,
            iterations: 0,
            server_calls: BTreeMap::new(),
            usage: LlmUsage::default(),
            last_prompt_tokens: None,
            compactions: 0,
            loop_abort: None,
            session_path: None,
        }
    }
}

