/// User-supplied settings for a single `run` invocation.
pub struct RunSettings {
    pub agent_def_path: PathBuf,
    pub in_session: Option<PathBuf>,
    pub prompt_file: Option<PathBuf>,
    pub out_session: Option<PathBuf>,
    pub template_path: Option<PathBuf>,
    pub tools_file: Option<PathBuf>,
    pub skills_dir: Option<PathBuf>,
    /// A ceiling on turns, if the caller asked for one. `None` is unbounded.
    pub max_iterations: Option<u32>,
    /// A ceiling on wall-clock time, if the caller asked for one. `None` is unbounded.
    pub max_runtime: Option<Duration>,
    /// A path whose existence means "stop at the next iteration", if the caller wants
    /// to be able to say so. `None` is a run nothing outside it can interrupt.
    ///
    /// Not read from `atoma.toml`, unlike the two ceilings: a path that is fixed in
    /// configuration is a path that might already exist when a run starts, which would
    /// stop every run immediately. It belongs to one invocation.
    pub stop_file: Option<PathBuf>,
    /// Whether a completion cut off for repeating itself is re-asked.
    ///
    /// `false` -- the default -- means the run ends on the loop, which is what the
    /// countermeasure did before this existed. `true` means the loop is treated as a
    /// bad sample rather than a verdict: the aborted completion is discarded, a message
    /// telling the model what happened is appended, and the turn is asked for again.
    ///
    /// Unbounded, and that is deliberate. The run already has two ceilings --
    /// `max_runtime` and `stop_file` -- and the retry loop re-checks both before each
    /// re-ask, so a model that loops on every attempt is stopped by the clock or by a
    /// person. A count here would be a third ceiling guessing at the same thing.
    pub loop_retries: bool,
}

