56	export interface LoopAbort {
57	  /**
58	   * `identical_answers`, `cycle`, `empty_results` or `identical_failures` — the
59	   * snake_case wire values of atoma's `LoopRule`.
60	   */
61	  rule: string;
62	  /** The tool that repeated. */
63	  tool: string;
64	  /** Its arguments, as one line. */
65	  arguments: string;
66	  /** How many times it repeated. */
67	  count: number;
68	  /** Whether the answer was cut off by the per-server output cap. */
69	  capped: boolean;
70	  /** The tool's own sentence about the failure, for `identical_failures`. */
71	  lastError?: string;
72	}
73	
74	/**
75	 * The verdict, when this run was stopped by the loop guard.
76	 *
77	 * `undefined` is every other case, and it includes the one a pin has to allow for: a
78	 * session whose last run entry says `loop` but carries no verdict, which is what any
79	 * binary before v0.6.0 writes.
80	 */
81	export function loopAbortFromSession(session: Session | undefined): LoopAbort | undefined {
82	  const runs = session?.atoma_runs;
83	  if (!Array.isArray(runs) || runs.length === 0) return undefined;
84	  const last = runs[runs.length - 1] as { ended_because?: unknown; loop_abort?: unknown };
85	  if (last?.ended_because !== "loop") return undefined;
86	  const recorded = last.loop_abort;
87	  if (typeof recorded !== "object" || recorded === null) return undefined;
88	  const verdict = recorded as Record<string, unknown>;
89	  if (typeof verdict.rule !== "string" || verdict.rule === "") return undefined;
90	  return {
91	    rule: verdict.rule,
92	    tool: typeof verdict.tool === "string" ? verdict.tool : "",
93	    arguments: typeof verdict.arguments === "string" ? verdict.arguments : "",
94	    count: typeof verdict.count === "number" ? verdict.count : 0,
95	    capped: verdict.capped === true,
96	    lastError: typeof verdict.last_error === "string" && verdict.last_error !== "" ? verdict.last_error : undefined,
97	  };
98	}
99	
100	/** `4 times in a row`, or the words that fit a count worth no number. */
101	function times(count: number): string {
102	  return count > 1 ? `${count} times in a row` : "over and over";
103	}
104	
105	/**
106	 * What repeated, in the rule's own terms.
107	 *
108	 * Shared by the note and by the comment section so one fact is written once: a rule
109	 * described as "the same answer came back" in one place and "returned nothing" in the
110	 * other would be two accounts of one verdict.
111	 *
112	 * The arguments are deliberately not in here. They are their own line in both
113	 * readers, because one call's arguments can be a whole shell command and burying that
114	 * in a sentence makes the sentence unreadable and the arguments unquotable.
115	 */
116	export function repeatedCallSentence(abort: LoopAbort): string {
117	  const call = abort.tool === "" ? "a tool" : `\`${abort.tool}\``;
118	  const count = times(abort.count);
119	  switch (abort.rule) {
120	    case "identical_answers":
121	      return `it called ${call} ${count} and got the same answer back every time`;
122	    case "empty_results":
123	      return `it called ${call} ${count} and every call returned nothing`;
124	    case "identical_failures":
125	      return `it called ${call} ${count} and every call failed the same way`;
126	    case "cycle":
127	      return `the same calls, starting with ${call}, came round in a circle ${count}`;
128	    // A rule this reader does not know, which a newer core may add. It names the rule
129	    // and claims nothing else: describing an unknown rule as one of the four above is
130	    // the one thing this note must not do, because the run would act on a false fact.
131	    default:
132	      return `it called ${call} ${count} and repeating it got no further (\`${abort.rule}\`)`;
133	  }
134	}
135	
136	/** The line of arguments both readers show, or nothing when the verdict carried none. */
137	export function repeatedArguments(abort: LoopAbort): string | undefined {
138	  return abort.arguments === "" ? undefined : abort.arguments;
139	}
140	
141	/**
142	 * The note a loop-stopped run is handed before its one extra turn.
143	 *
144	 * It names the call, its arguments and the count, says in the rule's own words what
145	 * repeating it produced, and then names the way out: write the closing report or
146	 * verdict from what is already in hand. The cap gets its own paragraph because it
147	 * changes what "in hand" means — part of the answer was never delivered, so the run
148	 * has to work around it or change approach rather than read harder.
149	 */
150	export function loopContinuationMessage(abort: LoopAbort): string {
151	  const parts = [`Your run was stopped by the loop guard: ${repeatedCallSentence(abort)}.`];
152	  const argumentsItRepeated = repeatedArguments(abort);
153	  if (argumentsItRepeated !== undefined) parts.push(`The arguments it repeated were \`${argumentsItRepeated}\`.`);
154	  if (abort.capped) {
155	    parts.push(
156	      "The answer was also cut off by the output cap, so calling it again cannot reach what was cut. Work from what is there, or change the approach.",
157	    );
158	  }
159	  if (abort.lastError !== undefined) parts.push(`The failure it reported was:\n\n${abort.lastError}`);
160	  parts.push(nextStep(abort));
161	  return parts.join("\n\n");
162	}
163	
164	/** What to do instead of the call that repeated, per rule. */
165	function nextStep(abort: LoopAbort): string {
166	  switch (abort.rule) {
167	    case "identical_answers":
168	      return "That answer is already in this session above, so reading it again returns the same text. Use what is in hand: write the closing report, verdict or commit from what you have already read, or take the step that reading was for. Do not call it again.";
169	    case "empty_results":
170	      return "Calling it again returns nothing again. Either it is the wrong tool for what you are after, or what you are after is not there — answer from what the other calls already gave you, and write the closing report or the verdict now.";
171	    case "identical_failures":
172	      return "It will fail the same way again. Fix what the error names, reach for a different tool, or write the closing report and say what you could not do.";
173	    case "cycle":
174	      return "Each round is the same work over again, so repeating the calls cannot get past it. Take the next step the cycle was circling: write the closing report or the verdict from what is in hand.";
175	    default:
176	      return "Repeating it will not move the run on. Work from what is in hand, and write the closing report or the verdict next.";
177	  }
178	}
179	
180	/**
181	 * The section a result comment carries for a run the loop guard stopped.
182	 *
183	 * A run that never got its second turn, or that spent it on nothing, still tells the
184	 * person which call repeated without them opening the log. The blockquote is the
185	 * shape the other warnings on this comment already use, and it is a new section
186	 * rather than a restyle of the notice beside it.
187	 */
188	export function loopAbortLines(abort: LoopAbort): string[] {
189	  const lines = ["> [!WARNING]", `> The loop guard stopped this run: ${repeatedCallSentence(abort)}.`];
190	  const argumentsItRepeated = repeatedArguments(abort);
191	  if (argumentsItRepeated !== undefined) lines.push(`> The arguments it repeated were \`${argumentsItRepeated}\`.`);
192	  if (abort.capped) {
193	    lines.push("> The answer was cut off by the output cap, so repeating the call cannot reach what was cut.");
194	  }
195	  if (abort.lastError !== undefined) lines.push(`> It said: ${abort.lastError}`);
196	  return lines;
197	}

